import re
from datetime import datetime, timedelta, timezone
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def to_cents(value):
    if value is None or value == "":
        return 0
    try:
        amount = Decimal(str(value))
    except InvalidOperation:
        raise ValueError("Amount is not a number: " + str(value))
    return int((amount * 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))


brief = params.get("brief") or {}
budget = params.get("budget_cap") or {}
issues = []

# Claims: banned phrases, offer terms, unsubscribe link and sender address.
text = " ".join([str(brief.get("subject") or ""), str(brief.get("preheader") or ""), str(brief.get("body") or "")])
lowered = text.lower()
for phrase in str(params.get("banned_phrases") or "").split(","):
    phrase = phrase.strip().lower()
    if phrase and phrase in lowered:
        issues.append("The copy contains a phrase that needs evidence or removal: " + phrase)
if re.search(r"[%$]", text) and not str(brief.get("offerTerms") or "").strip():
    issues.append("The copy states a price or percentage but the offer terms are missing.")
if "unsubscribe" not in lowered and brief.get("unsubscribe") is not True:
    issues.append("There is no unsubscribe link.")
if not str(brief.get("senderAddress") or "").strip():
    issues.append("The sender's physical address is missing.")

# Spend against the budget cap, in whole cents.
estimated = params.get("estimated_cost")
cap = budget.get("amount")
within_budget = False
if estimated is None or cap is None:
    issues.append("The estimated cost or the budget cap is missing.")
else:
    within_budget = to_cents(estimated) <= to_cents(cap)
    if not within_budget:
        issues.append("The estimated cost is above the budget cap.")

# Timing: a valid UTC quarter-hour that leaves the minimum review lead.
campaign_id = str(params.get("campaign_id") or "")
if not campaign_id:
    issues.append("No draft campaign exists in the campaign tool yet.")
publish_at = str(params.get("publish_at") or "")
schedule_time = ""
try:
    parsed = datetime.fromisoformat(publish_at.replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    parsed = parsed.astimezone(timezone.utc)
    schedule_time = parsed.strftime("%Y-%m-%dT%H:%M:%S+00:00")
    if parsed.minute % 15 != 0 or parsed.second != 0:
        issues.append("The campaign tool only schedules on a quarter hour (:00, :15, :30, :45).")
    earliest = datetime.now(timezone.utc) + timedelta(days=float(params.get("lead_days") or 0))
    if parsed < earliest:
        issues.append("The publish time is sooner than the minimum review lead time.")
except ValueError:
    issues.append("The publish time is missing or is not a valid date and time.")

ok = len(issues) == 0
publish_request = {"campaignId": campaign_id, "scheduleTime": schedule_time} if ok else {}
